const tick = () => new Promise((r) => setTimeout(r, 16));
async function busy(on, text) { $('busy').hidden = !on; if (text) $('busy').textContent = text; if (on) await tick(); }

// The model is never moved on load. Rotating and scaling pivot on the model's own
