    if (axis === 'x') { Y = -z; Z = y; } else if (axis === 'y') { X = z; Z = -x; } else { X = -y; Y = x; }
    s[i] = X + c[0]; s[i + 1] = Y + c[1]; s[i + 2] = Z + c[2];
