// flat outline
S.flatView = 'side';
const FV = { fvTop: 'top', fvSide: 'side', fvFront: 'front' };
function syncFlatUI() { for (const id in FV) $(id).setAttribute('aria-pressed', S.flatView === FV[id]); }
for (const id in FV) $(id).addEventListener('click', () => { S.flatView = FV[id]; syncFlatUI(); });
$('flatT').addEventListener('input', (e) => { $('flatTOut').textContent = (+e.target.value).toFixed(1) + ' mm'; });
