        faces: faces.length, planes: count('plane'), cylinders: count('cyl'), cones: count('cone'), spheres: count('sphere'), tori: count('torus'),
        curvedDemoted: demoted, recognitionStopped: !!recog.stoppedEarly, unit: unitOut, fileUnit: input.unit, parts: input.parts,
        edges: topo.edges.length, verts: topo.verts.length, maxDeviation: maxDev, maxSnap: topo.maxSnap,
        snapFallback: topo.snapFallback, brokenLoops: topo.brokenLoops, tolerance: dTol, autoTolerance: autoTol,
        volume: Array.from(M.volumes).reduce((a, b) => a + b, 0), bbox: bb,
