// ---------- boot with sample ----------
initViewer();
updateDlHint();
const SAMPLES = { plate:[SAMPLE_B64, 'sample-mounting-plate.stl', 'Sample: mounting plate'], pin:[SAMPLE_PIN_B64, 'sample-turned-pin.stl', 'Sample: turned pin'], boss:[SAMPLE_BOSS_B64, 'sample-filleted-boss.stl', 'Sample: filleted boss'] };
